1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  describe("quote — base premiums", () => {
6	    it("empty item list → premium 5 G (processing fee only)", () => {
7	      const result = runScenario({
8	        customer: { yearsWithMHPCO: 0 },
9	        steps: [{ op: "quote", items: [] }],
10	      });
11	
12	      expect(result.results).toEqual([{ premium: 5 }]);
13	    });
14	    it.todo("a sword → base premium 100 G");
15	    it.todo("an amulet → base premium 60 G");
16	    it.todo("a staff → base premium 80 G");
17	    it.todo("a potion → base premium 40 G");
18	    it.todo("a single rune → base premium 25 G");
19	    it.todo("a single moonstone → base premium 25 G");
20	    it.todo("a sword and an amulet → policy base premium 160 G");
21	  });
22	
23	  describe("quote — building block of 3 alike components", () => {
24	    it.todo("2 runes → 50 G base premium");
25	    it.todo("3 runes → 60 G base premium (block applies)");
26	    it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
27	    it.todo("7 runes → 175 G base premium");
28	    it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
29	    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
30	  });
31	
32	  describe("quote — item-specific modifiers", () => {
33	    it.todo("a cursed sword → 50 G curse surcharge (50 % of the item's base premium)");
34	    it.todo("a sword with enchantment 5 → 30 G high-enchantment surcharge");
35	    it.todo("a sword with enchantment 4 → no high-enchantment surcharge");
36	    it.todo("a cursed sword with enchantment 5 → both surcharges apply");
37	    it.todo(
38	      "a cursed sword and a plain amulet → policy base 160 G, curse adds 50 G (50 % of the sword only) → 210 G before further modifiers and fee",
39	    );
40	  });
41	
42	  describe("quote — policy-wide modifiers", () => {
43	    it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
44	    it.todo("customer with 1 year with MHPCO → no loyalty discount");
45	    it.todo("a first quote carries the 10 % initial assessment surcharge");
46	    it.todo("the second quote in a scenario receives the 15 % follow-up contract discount");
47	    it.todo(
48	      "the first insurance surcharge still applies on a follow-up contract (each item is treated as a first insurance)",
49	    );
50	  });
51	
52	  describe("quote — rounding in the MHPCO's favour", () => {
53	    it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
54	    it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
55	  });
56	
57	  describe("quote — integration examples", () => {
58	    it.todo("newcomer (0 years) with a cursed steel sword, enchantment 3 → premium 165 G");
59	    it.todo(
60	      "long-standing customer (3 years), second quote, cursed steel sword, enchantment 7 → premium 160 G",
61	    );
62	  });
63	
64	  describe("claim — standard reimbursement", () => {
65	    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
66	    it.todo("damage to a rune (value 250 G), damage 200 G → payout 100 G (no special clause)");
67	  });
68	
69	  describe("claim — special clauses", () => {
70	    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
71	    it.todo(
72	      "dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement then deductible)",
73	    );
74	    it.todo(
75	      "dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (the 50 % rule wins)",
76	    );
77	    it.todo(
78	      "dragon-material sword, exactly enchantment 8, damage 1000 G → payout 400 G (high-enchantment clause applies, then deductible)",
79	    );
80	  });
81	
82	  describe("claim — deductible per damage event", () => {
83	    it.todo(
84	      "a dragon attack damages a sword (500 G) and an amulet (300 G) → payout 600 G (deductible once per damaged item)",
85	    );
86	    it.todo("a damage amount below the deductible does not produce a negative payout");
87	  });
88	
89	  describe("claim — multiple items of the same type", () => {
90	    it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
91	    it.todo(
92	      "two sword damage entries against a policy with two swords → each is a separate damage with its own deductible",
93	    );
94	  });
95	
96	  describe("claim — payout cap", () => {
97	    it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
98	    it.todo(
99	      "a cursed sword (premium with modifiers 165 G) → cap 2000 G (premium modifiers do not raise the cap)",
100	    );
101	    it.todo(
102	      "a policy covering a sword and 3 runes → insurance sum 1750 G (the block discount affects the premium only)",
103	    );
104	    it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remaining cap 600 G");
105	    it.todo(
106	      "sword policy, second successive claim of 1500 G → payout 600 G, remaining cap 0 G (reduced to the remaining cap)",
107	    );
108	  });
109	
110	  describe("claim — rounding in the MHPCO's favour", () => {
111	    it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
112	  });
113	
114	  describe("errors", () => {
115	    it.todo("a quote item with an unknown type (e.g. broomstick) is rejected");
116	    it.todo("a claim damaging an item that is not part of the policy is rejected");
117	    it.todo("a claim damaging an item of unknown type is rejected");
118	    it.todo(
119	      "a claim with more damage entries of a type than the policy covers (two swords, one insured) is rejected",
120	    );
121	    it.todo("a claim damage entry with amount -200 is rejected");
122	  });
123	
124	  describe("scenario processing", () => {
125	    it.todo("results are returned in the same order and length as the input steps");
126	    it.todo(
127	      "a claim refers to the policy created by an earlier quote step via its zero-based step index",
128	    );
129	  });
130	});
